const listMarketplaceListings = `-- name: ListMarketplaceListings :many
SELECT l.id, l.seller_user_id, u.username, u.display_name,
       l.category_slug, c.name AS category_name, l.title, l.description,
       l.price_idr, l.city, l.item_condition, l.latitude, l.longitude,
       l.status, l.created_at, l.updated_at,
       CASE WHEN $1::double precision IS NULL THEN NULL
            ELSE 6371.0088 * 2 * asin(sqrt(
                power(sin(radians(l.latitude - $2::double precision) / 2), 2) +
                cos(radians($2::double precision)) * cos(radians(l.latitude)) *
                power(sin(radians(l.longitude - $3::double precision) / 2), 2)
            ))
       END AS distance_km,
       EXISTS (
           SELECT 1 FROM marketplace_favorites f
           WHERE f.listing_id = l.id AND f.user_id = $4
       ) AS is_favorite
FROM marketplace_listings l
JOIN users u ON u.id = l.seller_user_id AND u.is_active = TRUE
JOIN marketplace_categories c ON c.slug = l.category_slug
WHERE l.status = 'active'
  AND ($5::text IS NULL OR l.category_slug = $5)
  AND ($6::text IS NULL OR lower(l.city) = lower($6))
  AND ($7::text IS NULL
       OR strpos(lower(l.title), lower($7)) > 0
       OR strpos(lower(l.description), lower($7)) > 0)
  AND ($8::bigint IS NULL OR l.price_idr >= $8)
  AND ($9::bigint IS NULL OR l.price_idr <= $9)
  AND ($1::double precision IS NULL OR (
      l.latitude IS NOT NULL
      AND l.longitude IS NOT NULL
      AND 6371.0088 * 2 * asin(sqrt(
          power(sin(radians(l.latitude - $2::double precision) / 2), 2) +
          cos(radians($2::double precision)) * cos(radians(l.latitude)) *
          power(sin(radians(l.longitude - $3::double precision) / 2), 2)
      )) <= $1::double precision
  ))
  AND ($10::timestamptz IS NULL
       OR (l.created_at, l.id) <
          ($10::timestamptz, $11::uuid))
ORDER BY l.created_at DESC, l.id DESC
LIMIT $12
`

